parameters.prompt:
=You are an expert binary options trading analyst. Analyze the market data and provide a trading signal.

Asset: {{ $json.asset }}
Timestamp: {{ $json.timestamp }}
Market Context: {{ $json.market_context }}

Respond ONLY with a valid JSON object in this exact format:
{
  "signal": "CALL" or "PUT" or "SKIP",
  "confidence": 0-100,
  "reasoning": "brief explanation"
}

Be decisive. Only use SKIP if market conditions are extremely unclear.

parameters.jsCode:
// AI Consensus Engine - Hybrid Strategy
// Requires 2+ agreement AND average confidence >70%

const items = $input.all();
const responses = [];

// Parse each AI response
for (const item of items) {
  try {
    let parsed;

    // Handle different response formats
    if (item.json.choices) {
      // OpenAI/DeepSeek format
      const content = item.json.choices[0]?.message?.content || item.json.choices[0]?.text;
      parsed = JSON.parse(content);
    } else if (item.json.content) {
      // Claude format
      const content = Array.isArray(item.json.content) 
        ? item.json.content[0].text 
        : item.json.content;
      parsed = JSON.parse(content);
    } else if (item.json.signal) {
      // Already parsed
      parsed = item.json;
    }

    if (parsed && parsed.signal && parsed.confidence !== undefined) {
      responses.push({
        model: item.json.model || 'unknown',
        signal: parsed.signal.toUpperCase(),
        confidence: parseFloat(parsed.confidence),
        reasoning: parsed.reasoning || 'No reasoning provided'
      });
    }
  } catch (error) {
    console.error('Failed to parse AI response:', error.message);
  }
}

// Ensure we have responses
if (responses.length === 0) {
  return [{
    json: {
      final_signal: 'SKIP',
      confidence: 0,
      consensus_reached: false,
      reason: 'No valid AI responses received',
      model_votes: {},
      timestamp: new Date().toISOString()
    }
  }];
}

// Count votes for each signal
const votes = { CALL: 0, PUT: 0, SKIP: 0 };
const confidences = { CALL: [], PUT: [], SKIP: [] };

for (const resp of responses) {
  const signal = resp.signal;
  if (votes.hasOwnProperty(signal)) {
    votes[signal]++;
    confidences[signal].push(resp.confidence);
  }
}

// Find majority signal (2+ votes)
let majoritySignal = null;
let maxVotes = Math.max(votes.CALL, votes.PUT, votes.SKIP);

if (maxVotes >= 2) {
  if (votes.CALL === maxVotes) majoritySignal = 'CALL';
  else if (votes.PUT === maxVotes) majoritySignal = 'PUT';
  else if (votes.SKIP === maxVotes) majoritySignal = 'SKIP';
}

// Calculate average confidence for majority signal
let avgConfidence = 0;
let finalSignal = 'SKIP';
let consensusReached = false;
let reason = '';

if (majoritySignal && confidences[majoritySignal].length > 0) {
  avgConfidence = confidences[majoritySignal].reduce((a, b) => a + b, 0) / confidences[majoritySignal].length;

  // Hybrid rule: 2+ agreement AND >70% confidence
  if (avgConfidence >= 70 && majoritySignal !== 'SKIP') {
    finalSignal = majoritySignal;
    consensusReached = true;
    reason = `${votes[majoritySignal]}/${responses.length} models agree on ${majoritySignal} with ${avgConfidence.toFixed(1)}% avg confidence`;
  } else if (avgConfidence < 70) {
    finalSignal = 'SKIP';
    reason = `Confidence too low: ${avgConfidence.toFixed(1)}% < 70% threshold`;
  } else {
    finalSignal = 'SKIP';
    reason = 'Models agree on SKIP';
  }
} else {
  finalSignal = 'SKIP';
  reason = 'No majority consensus (all models disagree)';
}

// Build detailed model votes
const modelVotes = responses.map(r => ({
  model: r.model,
  signal: r.signal,
  confidence: r.confidence,
  reasoning: r.reasoning
}));

return [{
  json: {
    final_signal: finalSignal,
    confidence: Math.round(avgConfidence * 10) / 10,
    consensus_reached: consensusReached,
    reason: reason,
    votes_breakdown: votes,
    model_votes: modelVotes,
    total_models: responses.length,
    asset: items[0]?.json?.asset || 'UNKNOWN',
    timestamp: new Date().toISOString()
  }
}];
